  "notes": {
    "11341980_23": {"legal_reason":"关注立法要处理的现实条件而非抽象理论；须读其对法规覆盖范围的论证。", "protocol_note":"GRAND可依现实目的编码；NONE反映孤段难见完整推论", "impact":"旧案功能性解释容易被漏检。"},
    "3672856_34": {"legal_reason":"从税种概念及定义厘清类别，定义本身不证明整个裁判仅由规则机械推出。", "protocol_note":"FORMAL依分类词义可接受；模型NONE可能因其为铺垫。", "impact":"概念段落不宜独立作案件筛选。"},
    "81100_69": {"legal_reason":"所引国务卿沟通涉及立法背景；事实性转述不必然构成政策式推理。", "protocol_note":"GRAND依历史目的解释可以成立；NONE依纯叙述亦可成立。", "impact":"低置信立法史应回看完整意见。"},
    "3612156_42": {"legal_reason":"针对诉讼不中止的法条目的释义，非单纯程序叙述。", "protocol_note":"GRAND依立法目的可复现；NONE因短句归纳可理解。", "impact":"历史措辞与OCR降低稳定性。"},
    "6931942_17": {"legal_reason":"承认从严解释刑法的一般规则，但其后可能转向适用理由；不能只凭规则开头定义立场。", "protocol_note":"GRAND取全段转折；FORMAL取严格解释法则，两种均需查后文。", "impact":"规则与目的并列须强制精读。"},
    "5655150_280": {"legal_reason":"涉及法定货币条款的合宪性讨论，异议意见不能充当法院多数裁判理由。", "protocol_note":"FORMAL依宪法规则推断可接受；NONE可能因本段为意见过渡。", "impact":"案件层面不可把异议当作holding。"},
    "3385333_19": {"legal_reason":"立法用语owner的范围与主张相对，取决于词义还是立法目标。", "protocol_note":"GRAND取目的考虑；FORMAL取字词分析，需保留争议。", "impact":"早期词义段不适合自动排他筛选。"},
    "11341177_13": {"legal_reason":"总统命令与国会授权的界限是实质法律判断，多数意见上下文限制行政权。", "protocol_note":"FORMAL按权限规则可复现；NONE若仅孤段罗列命令不足。", "impact":"精读应追踪授权基础而非风格分。"},
    "6139418_72": {"legal_reason":"社会对独立司法的依赖属于制度后果论，但文本是异议，不能当多数见解。", "protocol_note":"GRAND依社会价值可复现；NONE若仅一般前言亦可接受。", "impact":"制度价值与判决效力须区分。"},
    "11644460_32": {"legal_reason":"联邦官员被侵害罪的主观要件与联邦执法目的相连，应核对完整论证。", "protocol_note":"GRAND重目的；NONE认为反诘只是否认对方而未正面展开。", "impact":"刑法语境的筛选不能凭模型漏报排除。"},
    "1313717_86": {"legal_reason":"参议员对法条交叉援引的关切是一段立法史证据，单段不直接规定法条含义。", "protocol_note":"NONE因仅转述；GRAND因用于目的解释。", "impact":"低置信、异议与立法史交叉，必须复核。"},
    "12122490_155": {"legal_reason":"强调宪法问题加重法规解释争议；异议作者批评多数而非赞同多数理由。", "protocol_note":"FORMAL依解释优先顺序；GRAND依宪法回避权衡，均需上下文。", "impact":"不得拿异议风格冒充判决权威。"},
    "5861465_62": {"legal_reason":"协同意见明确主张文本足以决定结论，孤段也可辨别其自述方法。", "protocol_note":"FORMAL文本约束明显；GRAND可能被对其他解释方法的评论误导。", "impact":"短协同意见不得放大为多数意见标签。"},
    "6215707_64": {"legal_reason":"围绕狭义解释例外的司法自我约束展开；格言与政策考量并列。", "protocol_note":"NONE因是司法职能评论；FORMAL因约束性解释原则。", "impact":"工具难区分阐述法律规则与修辞。"},
    "8210237_68": {"legal_reason":"对offer的字典歧义进行批判是异议论证的一部分，不能只抓字典词形判断立场。", "protocol_note":"NONE为辩论铺垫；FORMAL可能由词典词汇诱发。", "impact":"词汇触发错误与异议身份限制律师检索价值。"}
  }
}"}

